<?php
namespace App\Domains\Events\Http\Controllers;
use App\Domains\Events\Models\StoredEvent; use App\Domains\Events\Services\EventBus; use App\Domains\Platform\Contracts\TenantContext; use Illuminate\Http\{JsonResponse,Request};
class EventController { public function __construct(private readonly EventBus $bus,private readonly TenantContext $tenant){} private function allow(Request $r,string $p):void{$r->user()->hasPermission($p)||abort(403);} public function index(Request $r):JsonResponse{$this->allow($r,'events.view');return response()->json(['data'=>StoredEvent::query()->where(fn($q)=>$q->whereNull('tenant_id')->orWhere('tenant_id',$this->tenant->id()))->when($r->query('type'),fn($q,$v)=>$q->where('event_type',$v))->latest('occurred_at')->paginate(50)]);} public function publish(Request $r):JsonResponse{$this->allow($r,'events.publish');$d=$r->validate(['event_type'=>['required','string','max:160'],'event_version'=>['sometimes','integer','min:1'],'aggregate_type'=>['nullable','string'],'aggregate_id'=>['nullable','string'],'correlation_id'=>['nullable','uuid'],'causation_id'=>['nullable','uuid'],'source_module'=>['required','string','max:80'],'payload'=>['required','array'],'tags'=>['nullable','array']]);return response()->json(['data'=>$this->bus->publish([...$d,'tenant_id'=>$this->tenant->id(),'actor_type'=>'user','actor_id'=>(string)$r->user()->id])],201);} public function replay(Request $r,string $event):JsonResponse{$this->allow($r,'events.replay');$model=StoredEvent::query()->where('tenant_id',$this->tenant->id())->findOrFail($event);return response()->json(['data'=>$this->bus->replay($model)],202);} }
